local GlassBatchSmelter = {}
local PRODUCTS = {
    raw_glass_batch = { name = "Surova steklena mešanica", sandCost = 3, sodaCost = 1, fuelCost = 2, time = 3, cost = 22, purity = 30, description = "Surova steklena mešanica iz peska in sode." },
    clear_glass = { name = "Bistro steklo", sandCost = 4, sodaCost = 1, fuelCost = 2, time = 5, cost = 55, purity = 50, prestige = 1, description = "Bistro steklo z nizko vsebnostjo nečistoč." },
    crystal_glass = { name = "Kristalno steklo", sandCost = 5, sodaCost = 1, leadCost = 1, fuelCost = 2, time = 7, cost = 130, purity = 70, prestige = 3, happiness = 1, description = "Kristalno steklo s svincem za sijaj." },
    lead_glass = { name = "Svinčevo steklo", sandCost = 5, sodaCost = 1, leadCost = 2, fuelCost = 2, time = 9, cost = 280, purity = 85, prestige = 6, happiness = 2, description = "Svinčevo steklo za fine izdelke." },
    silver_cleared_glass = { name = "Srebrno očiščeno steklo", sandCost = 6, sodaCost = 1, silverCost = 1, leadCost = 1, fuelCost = 2, time = 12, cost = 600, purity = 92, prestige = 12, happiness = 3, description = "Steklo očiščeno s srebrom za plemiče." },
    royal_grand_glass = { name = "Kraljevski veliki steklo", sandCost = 10, goldCost = 1, silverCost = 1, jewelCost = 1, sodaCost = 2, leadCost = 2, fuelCost = 3, time = 17, cost = 1800, purity = 100, prestige = 36, happiness = 8, description = "Veliko kraljevsko steklo z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Steklarska livarna", cost = { gold = 320, wood = 140, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    furnace = { name = "Talilna peč", cost = { gold = 1100, wood = 300, stone = 500, fuel = 10 }, upkeep = 27, qualityBonus = 18 },
    annealing_oven = { name = "Ohlajevalna peč", cost = { gold = 2500, wood = 400, stone = 800, silver = 40, sand = 10 }, upkeep = 62, qualityBonus = 30 },
    royal_glass_atelier = { name = "Kraljevski atelje stekla", cost = { gold = 10000, wood = 600, stone = 1100, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 45 },
}
GlassBatchSmelter.sandStock = 24; GlassBatchSmelter.sodaStock = 14; GlassBatchSmelter.leadStock = 12; GlassBatchSmelter.fuelStock = 16; GlassBatchSmelter.silverStock = 8; GlassBatchSmelter.goldStock = 6; GlassBatchSmelter.jewelStock = 6
GlassBatchSmelter.productStock = {}; GlassBatchSmelter.buildings = {}; GlassBatchSmelter.maker = nil; GlassBatchSmelter.activeMaking = {}; GlassBatchSmelter.totalProducts = 0; GlassBatchSmelter.dayTimer = 0
function GlassBatchSmelter.init() GlassBatchSmelter.sandStock=24; GlassBatchSmelter.sodaStock=14; GlassBatchSmelter.leadStock=12; GlassBatchSmelter.fuelStock=16; GlassBatchSmelter.silverStock=8; GlassBatchSmelter.goldStock=6; GlassBatchSmelter.jewelStock=6; GlassBatchSmelter.productStock={}; GlassBatchSmelter.buildings={}; GlassBatchSmelter.maker=nil; GlassBatchSmelter.activeMaking={}; GlassBatchSmelter.totalProducts=0; GlassBatchSmelter.dayTimer=0; print("[GlassBatchSmelter] Royal Glass Batch Smelter System initialized (6 products, 4 buildings)") end
function GlassBatchSmelter.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBatchSmelter.maker={name=n or ("Steklar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklar najet: %s (spretnost: %d)",GlassBatchSmelter.maker.name,s),"success") end; return true end
function GlassBatchSmelter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBatchSmelter.build(id) local ok,e=GlassBatchSmelter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBatchSmelter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBatchSmelter.getQualityBonus() local b=0; for _,bd in ipairs(GlassBatchSmelter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBatchSmelter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.sandCost and GlassBatchSmelter.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.sodaCost and GlassBatchSmelter.sodaStock<(d.sodaCost or 0) then return false,"Premalo sode" end; if d.leadCost and GlassBatchSmelter.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.fuelCost and GlassBatchSmelter.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and GlassBatchSmelter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBatchSmelter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBatchSmelter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #GlassBatchSmelter.buildings==0 then return false,"Potrebna delavnica" end; if not GlassBatchSmelter.maker then return false,"Potreben steklar" end; return true end
function GlassBatchSmelter.make(pt,qty) qty=qty or 5; local ok,e=GlassBatchSmelter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.sandCost then GlassBatchSmelter.sandStock=GlassBatchSmelter.sandStock-d.sandCost*qty end; if d.sodaCost then GlassBatchSmelter.sodaStock=GlassBatchSmelter.sodaStock-d.sodaCost*qty end; if d.leadCost then GlassBatchSmelter.leadStock=GlassBatchSmelter.leadStock-d.leadCost*qty end; if d.fuelCost then GlassBatchSmelter.fuelStock=GlassBatchSmelter.fuelStock-d.fuelCost*qty end; if d.silverCost then GlassBatchSmelter.silverStock=GlassBatchSmelter.silverStock-d.silverCost*qty end; if d.goldCost then GlassBatchSmelter.goldStock=GlassBatchSmelter.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBatchSmelter.jewelStock=GlassBatchSmelter.jewelStock-d.jewelCost*qty end; local t=d.time; if GlassBatchSmelter.maker then t=math.max(1,t-math.floor(GlassBatchSmelter.maker.skill/12)) end; table.insert(GlassBatchSmelter.activeMaking,{id="glassbatch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBatchSmelter.completeMaking(m) local q=1.0+(GlassBatchSmelter.getQualityBonus()/100); if GlassBatchSmelter.maker then q=q+(GlassBatchSmelter.maker.skill/150) end; q=math.min(2.5,q); GlassBatchSmelter.productStock[m.productType]=(GlassBatchSmelter.productStock[m.productType] or 0)+m.quantity; GlassBatchSmelter.totalProducts=GlassBatchSmelter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBatchSmelter.maker then GlassBatchSmelter.maker.itemsMade=GlassBatchSmelter.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBatchSmelter.maker.skill=math.min(100,GlassBatchSmelter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassbatch.completed",{productName=m.productName,purity=m.purity}) end end
function GlassBatchSmelter.update(dt) if not _G.state then return end; GlassBatchSmelter.dayTimer=GlassBatchSmelter.dayTimer+dt; if GlassBatchSmelter.dayTimer>=30 then GlassBatchSmelter.dayTimer=0; for i=#GlassBatchSmelter.activeMaking,1,-1 do local m=GlassBatchSmelter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBatchSmelter.completeMaking(m); table.remove(GlassBatchSmelter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBatchSmelter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBatchSmelter.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBatchSmelter.getStats() return {sandStock=GlassBatchSmelter.sandStock,sodaStock=GlassBatchSmelter.sodaStock,leadStock=GlassBatchSmelter.leadStock,fuelStock=GlassBatchSmelter.fuelStock,silverStock=GlassBatchSmelter.silverStock,goldStock=GlassBatchSmelter.goldStock,jewelStock=GlassBatchSmelter.jewelStock,productStock=GlassBatchSmelter.productStock,numBuildings=#GlassBatchSmelter.buildings,hasMaker=GlassBatchSmelter.maker~=nil,makerName=GlassBatchSmelter.maker and GlassBatchSmelter.maker.name or "—",makerSkill=GlassBatchSmelter.maker and GlassBatchSmelter.maker.skill or 0,activeMaking=#GlassBatchSmelter.activeMaking,totalProducts=GlassBatchSmelter.totalProducts} end
return GlassBatchSmelter
